select *, count(balance) over (partition by customer_id order by opened_date, id rows between 2 preceding and current row) as last3_count_balance, max(balance) over (partition by customer_id order by opened_date, id rows between 2 preceding and current row) as last3_max_balance, avg(balance) over (partition by customer_id order by opened_date, id rows between 2 preceding and current row) as last3_avg_balance, min(balance) over (partition by customer_id order by opened_date, id rows between 2 preceding and current row) as last3_min_balance, ntile(4) over (partition by status order by balance desc, id) as balance_bucket from accounts;
